package net.runelite.client.config;

import java.lang.reflect.Type;
import lombok.Value;

@Value
public class ConfigItemDescriptor implements ConfigObject
{
	private final ConfigItem item;
	private final Type type;
	private final Range range;
	private final Alpha alpha;
	private final Units units;

	@Override
	public String key()
	{
		return item.keyName();
	}

	@Override
	public String name()
	{
		return item.name();
	}

	@Override
	public int position()
	{
		return item.position();
	}
}

package tccrewplugin.api;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import tccrewplugin.clanchat.model.ClanWebhookPayload;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;

public class ClanWebhookApiClient extends ApiClient
{
	private final ApiRequestExecutor executor;

	public ClanWebhookApiClient(OkHttpClient httpClient, Gson gson)
	{
		super(httpClient, gson);
		this.executor = new ApiRequestExecutor(httpClient, gson);
	}

	public CompletableFuture<ApiResult<String>> send(
		String endpoint,
		String secret,
		ClanWebhookAuthenticationMode mode,
		ClanWebhookPayload payload
	)
	{
		if (endpoint == null || endpoint.trim().isEmpty())
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Endpoint is blank."));
		}

		Request.Builder builder = requestBuilder(endpoint)
			.post(createBody(mode, secret, payload))
			.header("Content-Type", "application/json");

		if (mode == ClanWebhookAuthenticationMode.BEARER_TOKEN)
		{
			builder.header("Authorization", "Bearer " + (secret == null ? "" : secret));
		}
		else if (mode == ClanWebhookAuthenticationMode.SECRET_HEADER)
		{
			builder.header("X-Clan-Webhook-Secret", secret == null ? "" : secret);
		}

		return executor.executePlain(builder.build());
	}

	private RequestBody createBody(ClanWebhookAuthenticationMode mode, String secret, ClanWebhookPayload payload)
	{
		if (mode == ClanWebhookAuthenticationMode.JSON_SECRET_FIELD)
		{
			Map<String, Object> envelope = new LinkedHashMap<>();
			envelope.put("secret", secret);
			envelope.put("payload", payload);
			return executor.jsonBody(envelope);
		}

		return executor.jsonBody(payload);
	}
}

package tccrewplugin.api;

public enum ClanWebhookAuthenticationMode
{
	BEARER_TOKEN,
	SECRET_HEADER,
	JSON_SECRET_FIELD;

	public static ClanWebhookAuthenticationMode fromConfig(String value)
	{
		if (value == null || value.trim().isEmpty())
		{
			return BEARER_TOKEN;
		}

		try
		{
			return valueOf(value.trim().toUpperCase());
		}
		catch (IllegalArgumentException ex)
		{
			return BEARER_TOKEN;
		}
	}
}

package tccrewplugin.clanchat;

public enum AccountType
{
	NORMAL(1),
	IRON(2),
	HARDCORE_IRON(3),
	ULTIMATE_IRON(4),
	UNRANKED_IRON(5),
	GROUP_IRON(6),
	HARDCORE_GROUP_IRON(7),
	PLAYER_MODERATOR(8),
	JAGEX_MODERATOR(9);

	private final int code;

	AccountType(int code)
	{
		this.code = code;
	}

	public int getCode()
	{
		return code;
	}
}

package tccrewplugin.clanchat;

import lombok.experimental.UtilityClass;

@UtilityClass
public class ClanAccountTypeResolver
{
	public AccountType getAccountType(String rawAuthor)
	{
		if (rawAuthor == null || rawAuthor.isBlank())
		{
			return AccountType.NORMAL;
		}

		if (rawAuthor.contains("<img=0>"))
		{
			return AccountType.PLAYER_MODERATOR;
		}
		if (rawAuthor.contains("<img=2>"))
		{
			return AccountType.IRON;
		}
		if (rawAuthor.contains("<img=10>"))
		{
			return AccountType.HARDCORE_IRON;
		}
		if (rawAuthor.contains("<img=3>"))
		{
			return AccountType.ULTIMATE_IRON;
		}
		if (rawAuthor.contains("<img=41>"))
		{
			return AccountType.GROUP_IRON;
		}
		if (rawAuthor.contains("<img=43>"))
		{
			return AccountType.UNRANKED_IRON;
		}
		if (rawAuthor.contains("<img=42>"))
		{
			return AccountType.HARDCORE_GROUP_IRON;
		}

		return AccountType.NORMAL;
	}
}

package tccrewplugin.clanchat;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.clan.ClanChannel;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.RuneScapeProfileType;
import okhttp3.OkHttpClient;
import tccrewplugin.PluginConstants;
import tccrewplugin.TangleCrewSyncConfig;
import tccrewplugin.api.ApiResult;
import tccrewplugin.api.ClanWebhookAuthenticationMode;
import tccrewplugin.clanchat.model.ClanMessageRecord;
import tccrewplugin.clanchat.model.ClanMessageType;
import tccrewplugin.clanchat.model.ClanWebhookEventType;
import tccrewplugin.clanchat.model.ClanWebhookPayload;
import tccrewplugin.clanchat.model.ClanWebhookPayload.Clan;
import tccrewplugin.clanchat.model.ClanWebhookPayload.Message;
import tccrewplugin.clanchat.model.ClanWebhookPayload.Player;
import tccrewplugin.clanchat.model.ClanWebhookStatus;
import tccrewplugin.util.TextSanitizer;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

@Slf4j
@Singleton
public class ClanChatService
{
	private final Client client;
	private final ClientThread clientThread;
	private final TangleCrewSyncConfig config;
	private final Gson gson;
	private final ScheduledExecutorService executor;
	private final ClanMessageFilter filter = new ClanMessageFilter();
	private volatile ClanMessageQueue queue;
	private final ClanWebhookDispatcher dispatcher;
	private final ClanMemberResolver clanMemberResolver = new ClanMemberResolver();
	private final AtomicBoolean shutdown = new AtomicBoolean();
	private final AtomicBoolean processing = new AtomicBoolean();
	private final AtomicReference<String> currentClanName = new AtomicReference<>();
	private final Deque<ClanMessageRecord> localHistory = new ArrayDeque<>();

	private volatile Instant lastCapturedMessageTime;
	private volatile Instant lastDeliveryAttempt;
	private volatile Instant lastSuccessfulDelivery;
	private volatile Integer lastHttpStatus;
	private volatile String lastError;
	private final AtomicInteger deliveredCount = new AtomicInteger();
	private final AtomicInteger filteredCount = new AtomicInteger();
	private final AtomicInteger failedCount = new AtomicInteger();
	private final AtomicInteger droppedCount = new AtomicInteger();
	private final AtomicInteger retriedCount = new AtomicInteger();
	private volatile boolean deliveriesPaused;

	@Inject
	public ClanChatService(Client client, ClientThread clientThread, TangleCrewSyncConfig config, Gson gson, ScheduledExecutorService executor, OkHttpClient httpClient)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.gson = gson;
		this.executor = executor;
		this.queue = new ClanMessageQueue(config.webhookQueueCapacity());
		this.dispatcher = new ClanWebhookDispatcher(httpClient, gson);
	}

	public void startUp()
	{
		shutdown.set(false);
		deliveriesPaused = !config.clanWebhookEnabled();
	}

	public void shutDown()
	{
		shutdown.set(true);
		queue.clear();
		filter.clear();
		localHistory.clear();
	}

	public void onConfigChanged(String key)
	{
		if ("clanWebhookEnabled".equals(key))
		{
			deliveriesPaused = !config.clanWebhookEnabled();
		}
		else if ("webhookQueueCapacity".equals(key))
		{
			rebuildQueue();
		}
	}

	public void onGameStateChanged(GameState gameState)
	{
		if (gameState != GameState.LOGGED_IN)
		{
			currentClanName.set(null);
		}
	}

	public void onClanChannelChanged(ClanChannel clanChannel)
	{
		currentClanName.set(clanMemberResolver.resolveClanName(clanChannel));
	}

	public void onChatMessage(String chatTypeName, String sender, String senderRank, String message, boolean guest)
	{
		if (shutdown.get())
		{
			return;
		}

		ClanMessageRecord record = ClanMessageClassifier.classify(
			chatTypeName,
			sender,
			senderRank,
			currentClanName.get(),
			message,
			client.getGameState() == GameState.LOGGED_IN ? client.getWorld() : null,
			guest,
			Instant.now(),
			false
		);
		lastCapturedMessageTime = record.getOccurredAt();

		ClanMessageFilter.Decision decision = filter.allow(config, record, client.getGameState() == GameState.LOGGED_IN, currentClanName.get());
		if (!decision.isAccepted())
		{
			filteredCount.incrementAndGet();
			appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), ClanMessageType.UNKNOWN, ClanWebhookStatus.FILTERED, null);
			if (config.debugLogging())
			{
				log.debug("Filtered clan message: {}", decision.getReason());
			}
			return;
		}

		if (!queue.offer(record))
		{
			droppedCount.incrementAndGet();
			appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), record.getType(), ClanWebhookStatus.DROPPED, null);
			return;
		}

		appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), record.getType(), ClanWebhookStatus.QUEUED, null);
		processQueue();
	}

	public void enqueueTestWebhook()
	{
		if (!config.clanWebhookEnabled())
		{
			lastError = "clan webhooks disabled";
			return;
		}
		ClanMessageRecord record = ClanMessageClassifier.classify("TEST", "Tangle Crew", null, currentClanName.get(), "Webhook test message", client.getWorld(), false, Instant.now(), true);
		if (!queue.offer(record))
		{
			lastError = "webhook queue full";
			return;
		}
		appendHistory(record, ClanWebhookEventType.TEST.name(), record.getType(), ClanWebhookStatus.QUEUED, null);
		processQueue();
	}

	public void pauseDeliveries()
	{
		deliveriesPaused = true;
	}

	public void resumeDeliveries()
	{
		deliveriesPaused = false;
		processQueue();
	}

	public synchronized void clearLocalHistory()
	{
		localHistory.clear();
	}

	public int getQueueSize()
	{
		return queue.size();
	}

	public int getQueueCapacity()
	{
		return queue.capacity();
	}

	public Instant getLastCapturedMessageTime()
	{
		return lastCapturedMessageTime;
	}

	public Instant getLastDeliveryAttempt()
	{
		return lastDeliveryAttempt;
	}

	public Instant getLastSuccessfulDelivery()
	{
		return lastSuccessfulDelivery;
	}

	public Integer getLastHttpStatus()
	{
		return lastHttpStatus;
	}

	public int getDeliveredCount()
	{
		return deliveredCount.get();
	}

	public int getFilteredCount()
	{
		return filteredCount.get();
	}

	public int getFailedCount()
	{
		return failedCount.get();
	}

	public int getDroppedCount()
	{
		return droppedCount.get();
	}

	public int getRetriedCount()
	{
		return retriedCount.get();
	}

	public String getCurrentClanName()
	{
		return currentClanName.get();
	}

	public synchronized List<ClanMessageRecord> getLocalHistory()
	{
		return new ArrayList<>(localHistory);
	}

	public String getLastError()
	{
		return lastError;
	}

	private synchronized void appendHistory(ClanMessageRecord record, String eventType, ClanMessageType type, ClanWebhookStatus status, Integer httpStatus)
	{
		while (localHistory.size() >= PluginConstants.DEFAULT_HISTORY_LIMIT)
		{
			localHistory.removeFirst();
		}
		localHistory.addLast(record);
		lastHttpStatus = httpStatus;
	}

	private void processQueue()
	{
		if (!processing.compareAndSet(false, true))
		{
			return;
		}

		executor.execute(() -> {
			try
			{
				if (deliveriesPaused || shutdown.get())
				{
					return;
				}
				ClanMessageRecord record = queue.poll();
				if (record == null)
				{
					return;
				}
				dispatchRecord(record);
			}
			finally
			{
				processing.set(false);
			}
		});
	}

	private synchronized void rebuildQueue()
	{
		ClanMessageQueue replacement = new ClanMessageQueue(config.webhookQueueCapacity());
		ClanMessageRecord record;
		while ((record = queue.poll()) != null)
		{
			if (!replacement.offer(record))
			{
				break;
			}
		}
		queue = replacement;
	}

	private void dispatchRecord(ClanMessageRecord record)
	{
		lastDeliveryAttempt = Instant.now();
		ClanWebhookPayload payload = toPayload(record);
		ClanWebhookAuthenticationMode mode = ClanWebhookAuthenticationMode.fromConfig(config.clanWebhookAuthenticationMode());
		CompletableFuture<ApiResult<String>> future = dispatcher.send(config.clanWebhookEndpoint(), config.clanWebhookSecret(), mode, payload);
		future.whenComplete((result, throwable) -> clientThread.invokeLater(() -> handleDeliveryResult(record, result, throwable)));
	}

	private void handleDeliveryResult(ClanMessageRecord record, ApiResult<String> result, Throwable throwable)
	{
		if (throwable != null)
		{
			failedCount.incrementAndGet();
			lastError = throwable.getMessage();
			appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), record.getType(), ClanWebhookStatus.FAILED, -1);
			processQueue();
			return;
		}

		lastHttpStatus = result.getStatusCode();
		if (result.isSuccess())
		{
			deliveredCount.incrementAndGet();
			lastSuccessfulDelivery = Instant.now();
			appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), record.getType(), ClanWebhookStatus.SENT, result.getStatusCode());
			processQueue();
			return;
		}

		boolean retryable = result.getStatusCode() == 408 || result.getStatusCode() == 425 || result.getStatusCode() == 429 || result.getStatusCode() >= 500;
		if (retryable && config.queueFailedWebhookMessages())
		{
			retriedCount.incrementAndGet();
			executor.schedule(() -> dispatchRecord(record), 1L, TimeUnit.SECONDS);
		}
		else
		{
			failedCount.incrementAndGet();
		}
		appendHistory(record, ClanWebhookEventType.CLAN_CHAT_MESSAGE.name(), record.getType(), ClanWebhookStatus.FAILED, result.getStatusCode());
		processQueue();
	}

	private ClanWebhookPayload toPayload(ClanMessageRecord record)
	{
		Integer world = config.includeWorldNumber() ? client.getWorld() : null;
		String username = client.getLocalPlayer() == null ? "" : client.getLocalPlayer().getName();
		ClanWebhookPayload.Player player = new Player(username, RuneScapeProfileType.getCurrent(client).name(), world);
		ClanWebhookPayload.Clan clan = new Clan(TextSanitizer.stripTags(currentClanName.get()));
		ClanWebhookPayload.Message message = new Message(
			record.getType().name(),
			config.includeSenderRank() ? record.getSender() : null,
			config.includeSenderRank() ? record.getSenderRank() : null,
			ClanMessageSanitizer.sanitize(record.getText(), config.redactUrls()),
			record.isGuest()
		);
		return new ClanWebhookPayload(
			PluginConstants.DEFAULT_CLAN_WEBHOOK_SCHEMA_VERSION,
			record.getEventId(),
			record.isTest() ? ClanWebhookEventType.TEST.name() : (record.getType() == ClanMessageType.CLAN_BROADCAST || record.getType() == ClanMessageType.GUEST_BROADCAST ? ClanWebhookEventType.CLAN_BROADCAST.name() : ClanWebhookEventType.CLAN_CHAT_MESSAGE.name()),
			config.includeTimestamp() ? Instant.now() : record.getOccurredAt(),
			PluginConstants.VERSION,
			player,
			clan,
			message,
			record.isTest()
		);
	}
}

package tccrewplugin.clanchat;

import tccrewplugin.TangleCrewConfig;
import tccrewplugin.TcCrewPlugin;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanChannel;
import net.runelite.api.clan.ClanID;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.ClanChannelChanged;
import net.runelite.client.RuneLite;
import org.apache.commons.lang3.StringUtils;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Optional;
import java.util.UUID;

@Slf4j
@Singleton
public class ClanChatWebhookManager
{
	private final Client client;
	private final TangleCrewConfig config;
	private final ClanWebhookService webhookService;
	private final ClanMemberTitleResolver titleResolver;

	private volatile boolean activeClan;

	@Inject
	public ClanChatWebhookManager(Client client, TangleCrewConfig config, ClanWebhookService webhookService, ClanMemberTitleResolver titleResolver)
	{
		this.client = client;
		this.config = config;
		this.webhookService = webhookService;
		this.titleResolver = titleResolver;
	}

	public void startUp()
	{
		activeClan = false;
		webhookService.startUp();
		refreshActiveClanState();
	}

	public void shutDown()
	{
		activeClan = false;
		webhookService.shutDown();
	}

	public void onConfigChanged(String key)
	{
		webhookService.onConfigChanged(key);
	}

	public void onClanChannelChanged(ClanChannelChanged event)
	{
		if (event.getClanId() != ClanID.CLAN)
		{
			return;
		}

		ClanChannel channel = event.getClanChannel();
		activeClan = channel != null && StringUtils.isNotBlank(ClanMessageSanitizer.normalizeWhitespace(channel.getName()));
	}

	public void onChatMessage(ChatMessage event)
	{
		if (event == null)
		{
			return;
		}

		ChatMessageType type = event.getType();
		if (type != ChatMessageType.CLAN_CHAT && type != ChatMessageType.CLAN_MESSAGE)
		{
			return;
		}

		Optional<ClanChannel> clanChannelOptional = getActiveClanChannel();
		if (!clanChannelOptional.isPresent())
		{
			return;
		}

		ClanChannel clanChannel = clanChannelOptional.get();
		if (!matchesConfiguredClan(clanChannel))
		{
			return;
		}

		if (type == ChatMessageType.CLAN_CHAT && !config.sendNormalChat())
		{
			return;
		}

		if (type == ChatMessageType.CLAN_MESSAGE && !config.sendSystemBroadcasts())
		{
			return;
		}

		String rawAuthor = event.getName();
		String author = ClanMessageSanitizer.sanitizeAuthor(rawAuthor);
		String content = ClanMessageSanitizer.sanitizeMessage(event.getMessage());
		if (content.isEmpty() || containsUnsupportedColorMarkup(content))
		{
			return;
		}

		AccountType accountType = ClanAccountTypeResolver.getAccountType(rawAuthor);
		SystemMessageType systemMessageType = ClanMessageClassifier.getSystemMessageType(event.getMessage(), type);
		if (systemMessageType == SystemMessageType.LOGIN && !config.sendLoginGuidance())
		{
			return;
		}
		if (systemMessageType == SystemMessageType.UNKNOWN && !config.sendUnknownBroadcasts())
		{
			return;
		}

		String clanTitle = type == ChatMessageType.CLAN_CHAT
			? titleResolver.resolveClanTitle(clanChannel, author)
			: null;

		ClanMessageEvent messageEvent = new ClanMessageEvent(
			author,
			content,
			accountType,
			systemMessageType,
			clanTitle,
			event.getTimestamp());
		messageEvent.setEventId(UUID.randomUUID().toString());
		messageEvent.setChatMessageType(type.name());

		if (config.includeClientMetadata())
		{
			messageEvent.setClanName(ClanMessageSanitizer.normalizeWhitespace(clanChannel.getName()));
			messageEvent.setPluginVersion(getPluginVersion());
			messageEvent.setRuneliteVersion(RuneLite.USER_AGENT);
		}

		if (config.debugLogging())
		{
			log.debug("Queued clan chat webhook event type={} classification={} author={}",
				type,
				systemMessageType,
				author);
		}

		webhookService.submit(messageEvent);
	}

	private void refreshActiveClanState()
	{
		Optional<ClanChannel> clanChannel = getActiveClanChannel();
		activeClan = clanChannel.isPresent()
			&& StringUtils.isNotBlank(ClanMessageSanitizer.normalizeWhitespace(clanChannel.get().getName()));
	}

	private Optional<ClanChannel> getActiveClanChannel()
	{
		ClanChannel clanChannel = client.getClanChannel();
		if (clanChannel == null)
		{
			return Optional.empty();
		}

		String name = ClanMessageSanitizer.normalizeWhitespace(clanChannel.getName());
		if (name.isEmpty())
		{
			return Optional.empty();
		}

		return Optional.of(clanChannel);
	}

	private boolean matchesConfiguredClan(ClanChannel clanChannel)
	{
		String configuredClanName = ClanMessageSanitizer.normalizeWhitespace(config.clanName());
		if (configuredClanName.isEmpty())
		{
			return true;
		}

		String activeClanName = ClanMessageSanitizer.normalizeWhitespace(clanChannel.getName());
		return !activeClanName.isEmpty() && configuredClanName.equalsIgnoreCase(activeClanName);
	}

	private boolean containsUnsupportedColorMarkup(String content)
	{
		// RuneLite clan chat format can leave closing color tags behind after sanitization.
		// The reference receiver does not handle those fragments safely, so suppress them.
		return content != null && content.contains("</col>");
	}

	private String getPluginVersion()
	{
		String version = TcCrewPlugin.class.getPackage() != null
			? TcCrewPlugin.class.getPackage().getImplementationVersion()
			: null;
		return StringUtils.defaultIfBlank(version, "unknown");
	}
}

