		this.executor = new ApiRequestExecutor(httpClient, gson);
	}

	public CompletableFuture<ApiResult<LfgConfigurationResponse>> fetchConfiguration(String baseUrl, String apiToken, String playerHeader, String pluginVersion)
	{
		HttpUrl url = parseUrl(normalizeBaseUrl(baseUrl), "/functions/v1/lfg-config");
		if (url == null)
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Invalid LFG Supabase URL."));
		}
		if (log.isDebugEnabled())
		{
			log.debug("LFG config request URL: {}", url);
		}
		Request request = requestBuilder(url.toString())
			.get()
			.header("Authorization", bearer(apiToken))
			.header("Content-Type", "application/json")
			.header("X-TcCrew-Player", safe(playerHeader))
			.header("X-Plugin-Version", safe(pluginVersion))
			.build();
		return executor.execute(request, LfgConfigurationResponse.class);
	}

	public CompletableFuture<ApiResult<LfgGroupsResponse>> fetchGroups(String baseUrl, String apiToken, String playerHeader, String pluginVersion)
	{
		HttpUrl url = parseUrl(normalizeBaseUrl(baseUrl), "/functions/v1/lfg-groups");
		if (url == null)
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Invalid LFG Supabase URL."));
		}
		if (log.isDebugEnabled())
		{
			log.debug("LFG groups request URL: {}", url);
		}
		Request request = requestBuilder(url.toString())
			.get()
			.header("Authorization", bearer(apiToken))
			.header("Content-Type", "application/json")
			.header("X-TcCrew-Player", safe(playerHeader))
			.header("X-Plugin-Version", safe(pluginVersion))
			.build();
		return executor.execute(request, LfgGroupsResponse.class);
	}

	public CompletableFuture<ApiResult<LfgActionResponse>> createGroup(String baseUrl, String apiToken, String playerHeader, String pluginVersion, String idempotencyKey, CreateLfgGroupRequest requestBody)
	{
		HttpUrl url = parseUrl(normalizeBaseUrl(baseUrl), "/functions/v1/lfg-groups");
		if (url == null)
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Invalid LFG Supabase URL."));
		}
		RequestBody body = executor.jsonBody(requestBody);
		Request request = requestBuilder(url.toString())
			.post(body)
			.header("Authorization", bearer(apiToken))
			.header("Content-Type", "application/json")
			.header("X-TcCrew-Player", safe(playerHeader))
			.header("X-Idempotency-Key", safe(idempotencyKey))
			.header("X-Plugin-Version", safe(pluginVersion))
			.build();
		return executor.execute(request, LfgActionResponse.class);
	}

	public CompletableFuture<ApiResult<LfgActionResponse>> actOnGroup(String baseUrl, String apiToken, String playerHeader, String pluginVersion, LfgActionRequest requestBody)
	{
		HttpUrl url = parseUrl(normalizeBaseUrl(baseUrl), "/functions/v1/lfg-group-action");
		if (url == null)
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Invalid LFG Supabase URL."));
		}
		RequestBody body = executor.jsonBody(requestBody);
		Request request = requestBuilder(url.toString())
			.post(body)
			.header("Authorization", bearer(apiToken))
			.header("Content-Type", "application/json")
			.header("X-TcCrew-Player", safe(playerHeader))
			.header("X-Idempotency-Key", safe(requestBody == null ? null : requestBody.getIdempotencyKey()))
			.header("X-Plugin-Version", safe(pluginVersion))
			.build();
		return executor.execute(request, LfgActionResponse.class);
	}

	private String bearer(String token)
	{
		return "Bearer " + safe(token);
	}

	private String safe(String value)
	{
		return value == null ? "" : value;
	}

	private String normalizeBaseUrl(String baseUrl)
	{
		HttpUrl url = HttpUrl.parse(baseUrl);
		if (url == null)
		{
			return baseUrl;
		}
		return url.newBuilder()
			.encodedPath("/")
			.query(null)
			.fragment(null)
			.build()
			.toString();
	}
}

package tccrewplugin.lfg;

import lombok.experimental.UtilityClass;
import org.apache.commons.lang3.StringUtils;
import tccrewplugin.lfg.model.LfgCategory;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

@UtilityClass
public class LfgCategoryFilter
{
	public Set<String> parseAllowList(String value)
	{
		Set<String> allowList = new LinkedHashSet<>();
		if (StringUtils.isBlank(value))
		{
			return allowList;
		}

		for (String token : value.split("[,;\\n]"))
		{
			String trimmed = token == null ? "" : token.trim();
			if (!trimmed.isEmpty())
			{
				allowList.add(trimmed.toLowerCase(Locale.ROOT));
			}
		}
		return allowList;
	}

	public List<LfgCategory> filterCategories(List<LfgCategory> categories, String allowListValue)
	{
		if (categories == null || categories.isEmpty())
		{
			return List.of();
		}

		Set<String> allowList = parseAllowList(allowListValue);
		List<LfgCategory> filtered = new ArrayList<>();
		for (LfgCategory category : categories)
		{
			if (category == null || !category.isEnabled())
			{
				continue;
			}
			if (allowList.isEmpty() || allowList.contains(normalize(category.getKey())))
			{
				filtered.add(category);
			}
		}
		return filtered;
	}

	public boolean matches(String categoryKey, String allowListValue)
	{
		if (StringUtils.isBlank(categoryKey))
		{
			return false;
		}
		Set<String> allowList = parseAllowList(allowListValue);
		return allowList.isEmpty() || allowList.contains(normalize(categoryKey));
	}

	private String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}
}

package tccrewplugin.lfg;

import lombok.experimental.UtilityClass;
import org.apache.commons.lang3.StringUtils;

import java.util.Collection;

@UtilityClass
public class LfgErrorSanitizer
{
	public String sanitize(String input, Collection<String> secrets)
	{
		if (StringUtils.isBlank(input))
		{
			return "";
		}

		String sanitized = input;
		if (secrets != null)
		{
			for (String secret : secrets)
			{
				if (StringUtils.isNotBlank(secret))
				{
					sanitized = sanitized.replace(secret, "[redacted]");
				}
			}
		}
		return sanitized.trim();
	}

	public String sanitizeThrowable(Throwable throwable, Collection<String> secrets)
	{
		String message = throwable == null ? "unknown error" : throwable.getMessage();
		return sanitize(message, secrets);
	}
}

package tccrewplugin.lfg;

import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import tccrewplugin.TangleCrewConfig;
import tccrewplugin.SettingsManager;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;

@Singleton
public class LfgNavigationManager
{
	private final ClientToolbar clientToolbar;
	private final LfgPanel panel;
	private final TangleCrewConfig config;
	private NavigationButton button;

	@Inject
	public LfgNavigationManager(ClientToolbar clientToolbar, LfgPanel panel, TangleCrewConfig config)
	{
		this.clientToolbar = clientToolbar;
		this.panel = panel;
		this.config = config;
	}

	public void startUp()
	{
		if (config.lfgEnabled())
		{
			addButton();
		}
	}

	public void shutDown()
	{
		removeButton();
	}

	public void onConfigChanged(net.runelite.client.events.ConfigChanged event)
	{
		if (!SettingsManager.CONFIG_GROUP.equals(event.getGroup()) || !"lfgEnabled".equals(event.getKey()))
		{
			return;
		}
		if (Boolean.parseBoolean(event.getNewValue()))
		{
			addButton();
		}
		else
		{
			removeButton();
		}
	}

	private void addButton()
	{
		if (button != null)
		{
			return;
		}
		BufferedImage icon = loadIcon();
		button = NavigationButton.builder()
			.tooltip("Tangle Crew LFG")
			.icon(icon)
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(button);
	}

	private void removeButton()
	{
		if (button == null)
		{
			return;
		}
		clientToolbar.removeNavigation(button);
		button = null;
	}

	private BufferedImage loadIcon()
	{
		try (InputStream iconStream = LfgNavigationManager.class.getResourceAsStream("/sidebar_icon.png"))
		{
			if (iconStream == null)
			{
				return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
			}
			BufferedImage icon = ImageIO.read(iconStream);
			return icon == null ? new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB) : icon;
		}
		catch (IOException ex)
		{
			return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		}
	}
}

