public class LfgCreateGroupPanel extends JPanel
{
	public interface CreateHandler
	{
		void onCreate(String categoryKey, String activity, String description, Instant startTime, Integer maximumPlayers);
	}

	private final JComboBox<LfgCategory> categoryBox = new JComboBox<>();
	private final JComboBox<LfgActivity> activityBox = new JComboBox<>();
	private final JTextField descriptionField = new JTextField();
	private final JComboBox<StartTimeOption> startTimeBox = new JComboBox<>(StartTimeOption.values());
	private final JTextField maximumPlayersField = new JTextField();
	private final JButton createButton = new JButton("Create Group");

	public LfgCreateGroupPanel(CreateHandler handler)
	{
		setLayout(new BorderLayout(4, 6));
		setOpaque(true);
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		setAlignmentX(Component.LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		JPanel form = new JPanel(new GridBagLayout());
		form.setOpaque(false);
		form.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		form.setAlignmentX(Component.LEFT_ALIGNMENT);
		form.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		GridBagConstraints gbc = new GridBagConstraints();
		gbc.insets = new java.awt.Insets(2, 0, 2, 6);
		gbc.fill = GridBagConstraints.HORIZONTAL;
		gbc.weightx = 1;
		gbc.gridx = 0;
		gbc.gridy = 0;
		addRow(form, gbc, "Category", categoryBox);
		addRow(form, gbc, "Activity", activityBox);
		addRow(form, gbc, "Start Time", startTimeBox);
		addRow(form, gbc, "Maximum Players", maximumPlayersField);
		addRow(form, gbc, "Description", descriptionField);

		LfgUiStyle.styleTextField(descriptionField);
		LfgUiStyle.styleTextField(maximumPlayersField);
		LfgUiStyle.styleComboBox(categoryBox);
		LfgUiStyle.styleComboBox(activityBox);
		LfgUiStyle.styleComboBox(startTimeBox);

		categoryBox.addActionListener(e -> refreshActivities());
		activityBox.addActionListener(e -> applySelectedActivityDefaults());

		LfgUiStyle.stylePrimaryButton(createButton);
		createButton.addActionListener(e -> {
			if (handler != null)
			{
				LfgCategory category = (LfgCategory) categoryBox.getSelectedItem();
				LfgActivity activity = (LfgActivity) activityBox.getSelectedItem();
				StartTimeOption startTimeOption = (StartTimeOption) startTimeBox.getSelectedItem();
				handler.onCreate(
					category == null ? "" : category.getKey(),
					activity == null ? "" : activity.getKey(),
					descriptionField.getText(),
					startTimeOption == null ? null : startTimeOption.toInstant(),
					parseMaximumPlayers(maximumPlayersField.getText())
				);
			}
		});

		JPanel footer = new JPanel(new BorderLayout());
		footer.setOpaque(false);
		footer.setAlignmentX(Component.LEFT_ALIGNMENT);
		footer.add(createButton, BorderLayout.CENTER);
		add(form, BorderLayout.CENTER);
		add(footer, BorderLayout.SOUTH);
	}

	public void setCategories(List<LfgCategory> categories)
	{
		categoryBox.removeAllItems();
		if (categories != null)
		{
			for (LfgCategory category : categories)
			{
				categoryBox.addItem(category);
			}
		}
		refreshActivities();
	}

	public void setBusy(boolean busy)
	{
		createButton.setEnabled(!busy);
		categoryBox.setEnabled(!busy);
		activityBox.setEnabled(!busy);
		descriptionField.setEnabled(!busy);
		startTimeBox.setEnabled(!busy);
		maximumPlayersField.setEnabled(!busy);
	}

	private void refreshActivities()
	{
		LfgActivity current = (LfgActivity) activityBox.getSelectedItem();
		String currentKey = current == null ? "" : String.valueOf(current.getKey());
		activityBox.removeAllItems();
		LfgCategory category = (LfgCategory) categoryBox.getSelectedItem();
		if (category != null && category.getActivities() != null)
		{
			for (LfgActivity activity : category.getActivities())
			{
				if (activity != null && activity.isEnabled())
				{
					activityBox.addItem(activity);
				}
			}
		}
		for (int i = 0; i < activityBox.getItemCount(); i++)
		{
			LfgActivity item = activityBox.getItemAt(i);
			if (item != null && currentKey.equalsIgnoreCase(String.valueOf(item.getKey())))
			{
				activityBox.setSelectedIndex(i);
				applySelectedActivityDefaults();
				return;
			}
		}
		if (activityBox.getItemCount() > 0)
		{
			activityBox.setSelectedIndex(0);
		}
		else
		{
			maximumPlayersField.setText("");
		}
		applySelectedActivityDefaults();
	}

	private void applySelectedActivityDefaults()
	{
		LfgActivity activity = (LfgActivity) activityBox.getSelectedItem();
		if (activity == null)
		{
			maximumPlayersField.setText("");
			return;
		}
		Integer maximumPlayers = activity.getMaximumPlayers();
		if (maximumPlayers != null)
		{
			maximumPlayersField.setText(String.valueOf(maximumPlayers));
		}
		else if (activity.isSupportsMass())
		{
			maximumPlayersField.setText("");
		}
	}

	private void addRow(JPanel form, GridBagConstraints gbc, String label, java.awt.Component component)
	{
		JLabel rowLabel = new JLabel(label);
		rowLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		rowLabel.setFont(rowLabel.getFont().deriveFont(Font.BOLD, 11f));
		gbc.weightx = 0;
		gbc.gridx = 0;
		form.add(rowLabel, gbc);
		gbc.weightx = 1;
		gbc.gridx = 1;
		form.add(component, gbc);
		gbc.gridy++;
	}

	private Integer parseMaximumPlayers(String value)
	{
		String trimmed = value == null ? "" : value.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		try
		{
			return Integer.parseInt(trimmed);
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private enum StartTimeOption
	{
		NOW("Now", null),
		IN_30_MINUTES("In 30 minutes", Duration.ofMinutes(30)),
		IN_1_HOUR("In 1 hour", Duration.ofHours(1)),
		IN_2_HOURS("In 2 hours", Duration.ofHours(2)),
		IN_4_HOURS("In 4 hours", Duration.ofHours(4)),
		IN_8_HOURS("In 8 hours", Duration.ofHours(8));

		private final String label;
		private final Duration offset;

		StartTimeOption(String label, Duration offset)
		{
			this.label = label;
			this.offset = offset;
		}

		Instant toInstant()
		{
			return offset == null ? null : Instant.now().plus(offset);
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
}

package tccrewplugin.lfg.ui;

import net.runelite.client.ui.ColorScheme;
import org.apache.commons.lang3.StringUtils;
import tccrewplugin.lfg.model.LfgGroup;
import tccrewplugin.lfg.model.LfgMember;
import tccrewplugin.util.Utils;

import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.BorderFactory;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.util.List;
import java.util.Locale;
import java.util.stream.Collectors;

public class LfgGroupCard extends JPanel
{
	public interface ActionHandler
	{
		void onJoin(LfgGroup group);

		void onLeave(LfgGroup group);

		void onClose(LfgGroup group);
	}

	private final JLabel title = new JLabel();
	private final JLabel meta = new JLabel();
	private final JLabel details = new JLabel();
	private final JLabel members = new JLabel();
	private final JLabel description = new JLabel();
	private final JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 6, 0));

	public LfgGroupCard()
	{
		setLayout(new BorderLayout(4, 4));
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR),
			BorderFactory.createEmptyBorder(8, 10, 8, 10)
		));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setAlignmentX(LEFT_ALIGNMENT);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		JPanel content = new JPanel();
		content.setOpaque(false);
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setAlignmentX(LEFT_ALIGNMENT);
		content.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

		title.setForeground(ColorScheme.BRAND_ORANGE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 13f));
		meta.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		details.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		members.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		description.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		title.setAlignmentX(LEFT_ALIGNMENT);
		meta.setAlignmentX(LEFT_ALIGNMENT);
		details.setAlignmentX(LEFT_ALIGNMENT);
		members.setAlignmentX(LEFT_ALIGNMENT);
		description.setAlignmentX(LEFT_ALIGNMENT);

		content.add(title);
		content.add(meta);
		content.add(details);
		content.add(members);
		content.add(description);
		add(content, BorderLayout.CENTER);

		actions.setOpaque(false);
		actions.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));
		actions.setAlignmentX(LEFT_ALIGNMENT);
		add(actions, BorderLayout.SOUTH);
	}

	public void setGroup(LfgGroup group, String currentPlayerId, ActionHandler handler)
	{
		actions.removeAll();
		if (group == null)
		{
			title.setText("");
			meta.setText("");
			details.setText("");
			members.setText("");
			description.setText("");
			actions.setVisible(false);
			return;
		}

		String category = group.getCategory() == null ? "Unknown" : group.getCategory().getDisplayName();
		String activity = StringUtils.defaultString(group.getActivity());
		String displayTitle = category + ": " + Utils.truncate(activity, 80);
		title.setText(displayTitle);
		title.setToolTipText(activity.length() > 80 ? activity : null);

		String start = group.getStartTime() == null ? "Now" : group.getStartTime().toString();
		String players = formatPlayers(group);
		String source = group.getSource() == null ? "Unknown" : group.getSource().name();
		String status = group.getStatus() == null ? "Unknown" : group.getStatus().name();
		meta.setText(String.format("%s \u2022 %s", source, status));
		details.setText(String.format("Start: %s  \u2022  Players: %s", start, players));

		List<LfgMember> memberList = group.getMembers() == null ? List.of() : group.getMembers();
		List<String> memberNames = memberList.stream()
			.map(LfgMember::getRsn)
			.filter(StringUtils::isNotBlank)
			.collect(Collectors.toList());
		if (memberNames.isEmpty())
		{
			members.setText("Members: None");
			members.setToolTipText(null);
		}
		else
		{
			members.setText(buildMembersHtml(memberNames));
			String tooltip = String.join(", ", memberNames);
			members.setToolTipText(tooltip.length() > 120 ? tooltip : null);
		}

		String desc = StringUtils.defaultString(group.getDescription());
		if (desc.isBlank())
		{
			description.setText("");
			description.setToolTipText(null);
		}
		else
		{
			description.setText("Description: " + Utils.truncate(desc, 120));
			description.setToolTipText(desc);
		}

		boolean canClose = group.getPermissions() != null && group.getPermissions().isCanClose();
		boolean canLeave = group.getPermissions() != null && group.getPermissions().isCanLeave();
		boolean canJoin = group.getPermissions() != null && group.getPermissions().isCanJoin();
		boolean currentMember = canLeave || isCurrentMember(group, currentPlayerId);

		JButton primary = new JButton(currentMember ? "Leave" : "Join");
		LfgUiStyle.stylePrimaryButton(primary);
		primary.setAlignmentX(LEFT_ALIGNMENT);
		primary.setEnabled(currentMember ? canLeave : canJoin);
		primary.addActionListener(e -> {
			if (handler == null)
			{
				return;
			}
			if (currentMember)
			{
				handler.onLeave(group);
			}
			else
			{
				handler.onJoin(group);
			}
		});

		actions.add(primary);
		if (canClose)
		{
			JButton close = new JButton("Close");
			LfgUiStyle.styleSecondaryButton(close);
			close.setAlignmentX(LEFT_ALIGNMENT);
			close.addActionListener(e -> {
				if (handler != null)
				{
					handler.onClose(group);
				}
			});
			actions.add(close);
		}
		actions.setVisible(actions.getComponentCount() > 0);
		setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
		revalidate();
		repaint();
	}

	private boolean isCurrentMember(LfgGroup group, String currentPlayerId)
	{
		if (StringUtils.isBlank(currentPlayerId) || group.getMembers() == null)
		{
			return false;
		}
		String normalized = currentPlayerId.trim().toLowerCase(Locale.ROOT);
		for (LfgMember member : group.getMembers())
		{
			if (member != null && StringUtils.isNotBlank(member.getRsn()) && normalized.equals(member.getRsn().trim().toLowerCase(Locale.ROOT)))
			{
				return true;
			}
		}
		return false;
	}

	private String formatPlayers(LfgGroup group)
	{
		int members = group.getMembers() == null ? 0 : group.getMembers().size();
		Integer maximum = group.getMaximumPlayers();
		if (maximum == null)
		{
			return members + " / unlimited";
		}
		return members + " / " + maximum;
	}

	private String buildMembersHtml(List<String> memberNames)
	{
		String lines = memberNames.stream()
			.map(this::escapeHtml)
			.collect(Collectors.joining("<br>"));
		return "<html>Members:<br>" + lines + "</html>";
	}

	private String escapeHtml(String value)
	{
		return value
			.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;");
	}
}

package tccrewplugin.lfg.ui;

import net.runelite.client.ui.ColorScheme;
