package tccrewplugin;

import tccrewplugin.util.Utils;
import lombok.Value;
import net.runelite.api.GameState;
import net.runelite.client.config.ConfigManager;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.NotNull;

import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Comparator;
import java.util.NavigableMap;
import java.util.SortedMap;
import java.util.TreeMap;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

@Singleton
public class VersionManager {
    public static final String VERSION_CONFIG_KEY = "pluginVersion";
    private static final long NOTIFICATION_DELAY_SECONDS = 3;
    private static final NavigableMap<Version, String> VERSIONS = new TreeMap<>(
        Comparator.comparingInt(Version::getMajor)
            .thenComparingInt(Version::getMinor)
            .thenComparingInt(Version::getPatch)
    );

    private final Version latest = VERSIONS.lastKey();

    @Inject
    private TcCrewPlugin plugin;

    @Inject
    private TangleCrewConfig config;

    @Inject
    private ConfigManager configManager;

    @Inject
    private SettingsManager settingsManager;

    @Inject
    private ScheduledExecutorService executor;

    void onStart() {
        if (config.pluginVersion().isEmpty()) {
            if (settingsManager.hasModifiedConfig()) {
                // Dink was already installed/used & launched for the first time since VersionManager was created
                setStoredVersion("1.8.4");
            } else {
                // first time launching Dink; no chat message necessary
                setStoredVersion(latest.toString());
            }
        }
    }

    void onGameState(GameState oldState, GameState newState) {
        if (newState != GameState.LOGGED_IN || oldState != GameState.LOGGING_IN) {
            // only check version when LOGGING_IN => LOGGED_IN
            return;
        }

        Version storedVersion = Version.of(config.pluginVersion());
        if (storedVersion == null || storedVersion.equals(latest)) {
            return;
        }

        setStoredVersion(latest.toString());
        executor.schedule(() -> {
            SortedMap<Version, String> latestUpdates = VERSIONS.tailMap(storedVersion, false);
            if (latestUpdates.isEmpty()) {
                return;
            }
            String displayVersion = latest.getPatch() == 0
                ? String.format("%d.%d.X", latest.getMajor(), latest.getMinor()) // avoids needing changelog for each patch
                : latest.toString();
            plugin.addChatMessage(
                "Updated to v" + displayVersion,
                Utils.GREEN,
                String.join("; ", latestUpdates.values())
            );
        }, NOTIFICATION_DELAY_SECONDS, TimeUnit.SECONDS);
    }

    void onProfileChange() {
        // if profile changes, set pluginVersion to latest so users don't see old changelogs on login
        setStoredVersion(latest.toString());
    }

    private void setStoredVersion(String version) {
        configManager.setConfiguration(SettingsManager.CONFIG_GROUP, VERSION_CONFIG_KEY, version);
    }

    private static void register(String version, String changelog) {
        VERSIONS.put(Version.of(version), changelog);
    }

    @Value
    private static class Version {
        int major;
        int minor;
        int patch;

        @Override
        public String toString() {
            return String.format("%d.%d.%d", major, minor, patch);
        }

        @Nullable
        public static Version of(@NotNull String version) {
            String[] parts = StringUtils.split(version, '.');
            if (parts.length < 3) return null;
            int major, minor, patch;
            try {
                major = Integer.parseInt(parts[0]);
                minor = Integer.parseInt(parts[1]);
                patch = Integer.parseInt(parts[2]);
            } catch (NumberFormatException ignored) {
                return null;
            }
            return new Version(major, minor, patch);
        }
    }

    static {
        register("1.9.0", "Notifications now report monster drop rarity");
        register("1.10.0", "Chat messages that match custom patterns can trigger notifications");
        register("1.10.1", "Level notifier now triggers at XP milestones with 5M as the default interval");
        register("1.10.2", "Chat notifier can read commands and RL notifications");
        register("1.10.5", "Pet notifications now report rarity and luck");
        register("1.10.12", "Rarity is now reported for notable pickpocket loot");
        register("1.10.14", "Kill count notifier now triggers for Herbiboar and Leagues notifier has been re-enabled");
        register("1.14.0", "League notifier is back!");
    }
}

package tccrewplugin.api;

import com.google.gson.Gson;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;

public abstract class ApiClient
{
	protected final OkHttpClient httpClient;
	protected final Gson gson;

	protected ApiClient(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	protected HttpUrl parseUrl(String baseUrl, String path)
	{
		HttpUrl base = HttpUrl.parse(baseUrl);
		if (base == null)
		{
			return null;
		}
		return base.newBuilder().addPathSegments(path.startsWith("/") ? path.substring(1) : path).build();
	}

	protected Request.Builder requestBuilder(String url)
	{
		return new Request.Builder().url(url);
	}
}

package tccrewplugin.api;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

import java.io.IOException;
import java.lang.reflect.Type;
import java.util.concurrent.CompletableFuture;

@Slf4j
public class ApiRequestExecutor
{
	public static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	private final OkHttpClient httpClient;
	private final Gson gson;

	public ApiRequestExecutor(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	public <T> CompletableFuture<ApiResult<T>> execute(Request request, Type responseType)
	{
		CompletableFuture<ApiResult<T>> future = new CompletableFuture<>();
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.complete(new ApiResult<>(-1, null, sanitizeError(e)));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					String bodyText = body == null ? "" : body.string();
					if (log.isDebugEnabled())
					{
						Request responseRequest = response.request();
						String encodedPath = responseRequest.url().encodedPath();
						if (encodedPath.startsWith("/functions/v1/lfg-"))
						{
							log.debug("LFG request completed: method={}, url={}, status={}", responseRequest.method(), responseRequest.url(), response.code());
							log.debug("LFG response body: bytes={}, body={}", bodyText.length(), sanitizeBody(bodyText));
						}
					}
					T parsed = bodyText.isEmpty() || responseType == null ? null : String.class.equals(responseType) ? (T) bodyText : gson.fromJson(bodyText, responseType);
					future.complete(new ApiResult<>(response.code(), parsed, response.isSuccessful() ? null : sanitizeBody(bodyText)));
				}
				catch (Exception ex)
				{
					future.complete(new ApiResult<>(response.code(), null, sanitizeError(ex)));
				}
			}
		});
		return future;
	}

	public CompletableFuture<ApiResult<String>> executePlain(Request request)
	{
		return execute(request, String.class);
	}

	public RequestBody jsonBody(Object value)
	{
		return RequestBody.create(JSON, gson.toJson(value));
	}

	private static String sanitizeBody(String body)
	{
		return body == null || body.isEmpty() ? "empty response" : body.length() > 512 ? body.substring(0, 512) + "..." : body;
	}

	private static String sanitizeError(Throwable error)
	{
		String message = error == null ? "unknown error" : error.getMessage();
		return message == null || message.isEmpty() ? "unknown error" : message.length() > 256 ? message.substring(0, 256) + "..." : message;
	}
}

package tccrewplugin.api;

public final class ApiResult<T>
{
	private final int statusCode;
	private final T body;
	private final String error;

	public ApiResult(int statusCode, T body, String error)
	{
		this.statusCode = statusCode;
		this.body = body;
		this.error = error;
	}

	public int getStatusCode()
	{
		return statusCode;
	}

	public T getBody()
	{
		return body;
	}

	public String getError()
	{
		return error;
	}

	public boolean isSuccess()
	{
		return statusCode >= 200 && statusCode < 300;
	}
}

package tccrewplugin.api;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import tccrewplugin.sync.model.SyncManifest;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CompletableFuture;

public class ManifestClient extends ApiClient
{
	private final ApiRequestExecutor executor;

	public ManifestClient(OkHttpClient httpClient, Gson gson)
	{
		super(httpClient, gson);
		this.executor = new ApiRequestExecutor(httpClient, gson);
	}

	public CompletableFuture<SyncManifest> fetchManifest(String baseUrl)
	{
		if (baseUrl == null || baseUrl.trim().isEmpty())
		{
			return CompletableFuture.failedFuture(new IllegalArgumentException("API base URL is blank."));
		}

		okhttp3.HttpUrl url = parseUrl(baseUrl, "/api/sync/manifest");
		if (url == null)
		{
			return CompletableFuture.failedFuture(new IllegalArgumentException("API base URL is invalid."));
		}

		Request request = requestBuilder(url.toString()).get().build();
		return executor.executePlain(request).thenApply(result -> {
			if (!result.isSuccess())
			{
				throw new IllegalArgumentException("Manifest request failed with HTTP " + result.getStatusCode() + (result.getError() == null ? "" : ": " + result.getError()));
			}

			try
			{
				SyncManifest manifest = gson.fromJson(result.getBody(), SyncManifest.class);
				return validate(manifest);
			}
			catch (JsonParseException ex)
			{
				throw new IllegalArgumentException("Manifest response was malformed.", ex);
			}
		});
	}

	private SyncManifest validate(SyncManifest manifest)
	{
		if (manifest == null)
		{
			throw new IllegalArgumentException("Manifest response was empty.");
		}

		List<Integer> varbits = manifest.getVarbits() == null ? List.of() : new ArrayList<>(manifest.getVarbits());
		List<Integer> varps = manifest.getVarps() == null ? List.of() : new ArrayList<>(manifest.getVarps());
		List<Integer> clogs = manifest.getCollectionLogItems() == null ? List.of() : new ArrayList<>(manifest.getCollectionLogItems());
		return new SyncManifest(manifest.getVersion(), varbits, varps, clogs);
	}
}

package tccrewplugin.api;

import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import tccrewplugin.PluginConstants;
import tccrewplugin.sync.model.PlayerSubmission;

import java.util.concurrent.CompletableFuture;

public class PlayerSyncApiClient extends ApiClient
{
	private final ApiRequestExecutor executor;

	public PlayerSyncApiClient(OkHttpClient httpClient, Gson gson)
	{
		super(httpClient, gson);
		this.executor = new ApiRequestExecutor(httpClient, gson);
	}

	public CompletableFuture<ApiResult<String>> submit(String baseUrl, String apiToken, PlayerSubmission submission)
	{
		okhttp3.HttpUrl url = parseUrl(baseUrl, "/api/sync/submit");
		if (url == null)
		{
			return CompletableFuture.completedFuture(new ApiResult<>(-1, null, "Invalid API base URL."));
		}

		RequestBody body = executor.jsonBody(submission);
		Request request = requestBuilder(url.toString())
			.post(body)
			.header("Authorization", "Bearer " + (apiToken == null ? "" : apiToken))
			.header("Content-Type", "application/json")
			.build();
		return executor.executePlain(request);
	}
}

