package tccrewplugin.notifiers.data;

import tccrewplugin.domain.LootCriteria;
import tccrewplugin.util.Sanitizable;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import lombok.ToString;

import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;

@Getter
@ToString(callSuper = true)
@EqualsAndHashCode(callSuper = true)
public class AnnotatedItemStack extends SerializedItemStack implements Sanitizable {
    private final Set<LootCriteria> criteria;

    public AnnotatedItemStack(int id, int quantity, long priceEach, String name, Set<LootCriteria> criteria) {
        super(id, quantity, priceEach, name);
        this.criteria = criteria;
    }

    @Override
    public Map<String, Object> sanitized() {
        var m = new HashMap<>(super.sanitized());
        m.put("criteria", criteria.stream().map(Objects::toString).collect(Collectors.toSet()));
        return m;
    }

    public static AnnotatedItemStack of(SerializedItemStack i, Set<LootCriteria> criteria) {
        return new AnnotatedItemStack(i.getId(), i.getQuantity(), i.getPriceEach(), i.getName(), criteria);
    }
}

package tccrewplugin.notifiers.data;

import com.google.gson.annotations.JsonAdapter;
import tccrewplugin.message.Field;
import tccrewplugin.util.DurationAdapter;
import lombok.EqualsAndHashCode;
import lombok.Value;
import lombok.With;
import lombok.experimental.Accessors;
import org.jetbrains.annotations.Nullable;

import java.time.Duration;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

@With
@Value
@EqualsAndHashCode(callSuper = false)
public class BossNotificationData extends NotificationData {
    String boss;
    Integer count;
    String gameMessage;
    @JsonAdapter(DurationAdapter.class)
    Duration time;
    @Accessors(fluent = true)
    Boolean isPersonalBest;
    @Nullable
    @JsonAdapter(DurationAdapter.class)
    Duration personalBest;
    @Nullable
    Collection<String> party;

    @Override
    public List<Field> getFields() {
        if (party != null && !party.isEmpty()) {
            return List.of(new Field("Party Size", Field.formatBlock("", String.valueOf(party.size()))));
        }
        return super.getFields();
    }

