    {
        String value = input.getValue();
        if (value == null)
        {
            return;
        }

        String command = value.trim().toLowerCase(Locale.ROOT);
        if (command.isEmpty())
        {
            return;
        }

        if (command.startsWith("!clogpayload"))
        {
            input.consume();
            onManualClogPayload();
        }
        else if (command.startsWith("!clogsync"))
        {
            input.consume();
            onManualClogSync();
        }
        else if (command.startsWith("!clogstatus"))
        {
            input.consume();
            onManualClogStatus();
        }
        else if (command.startsWith("!pball"))
        {
            input.consume();
            onManualPbAll();
        }
        else if (command.startsWith("!syncall"))
        {
            input.consume();
            onManualSyncAll();
        }
    }

