import okhttp3.OkHttpClient;
import okhttp3.MultipartBody;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import tccrewplugin.TangleCrewConfig;
import tccrewplugin.TcCrewPlugin;
import tccrewplugin.sync.model.CollectionLogSnapshot;
import tccrewplugin.sync.model.PersonalBestSummary;
import tccrewplugin.sync.model.SyncPayload;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import javax.inject.Inject;
import javax.inject.Singleton;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.time.Duration;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

@Slf4j
@Singleton
public class ClogPbWebhookClient
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final int MAX_QUEUE_SIZE = 5;
    private static final int MAX_ATTEMPTS = 3;
    private static final Duration CONNECT_TIMEOUT = Duration.ofSeconds(10);
    private static final Duration CALL_TIMEOUT = Duration.ofSeconds(20);
    private static final Duration BASE_RETRY_DELAY = Duration.ofSeconds(2);
    private static final int DISCORD_INLINE_JSON_LIMIT = 1800;
    private static final String DISCORD_JSON_FILENAME = "clog-pb-sync.json";

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;
    private final Gson gson;
    private final TangleCrewConfig config;
    private final Object queueLock = new Object();
    private final Deque<QueuedUpload> queue = new ArrayDeque<>();
    private final Deque<ScheduledFuture<?>> retryFutures = new ArrayDeque<>();
    private final SecureRandom random = new SecureRandom();

    private volatile boolean started;
    private volatile boolean shuttingDown;
    private volatile Call currentCall;

    @Inject
    public ClogPbWebhookClient(OkHttpClient httpClient, ScheduledExecutorService executor, Gson gson, TangleCrewConfig config)
    {
        this.httpClient = httpClient;
        this.executor = executor;
        this.gson = gson;
        this.config = config;
    }

    public void start()
    {
        started = true;
        shuttingDown = false;
    }

    public void shutdown()
    {
        shuttingDown = true;
        synchronized (queueLock)
        {
            queue.clear();
            if (currentCall != null)
            {
                currentCall.cancel();
                currentCall = null;
            }
            while (!retryFutures.isEmpty())
            {
                ScheduledFuture<?> future = retryFutures.pollFirst();
                if (future != null)
                {
                    future.cancel(false);
                }
            }
        }
    }

    public boolean hasPendingWork()
    {
        synchronized (queueLock)
        {
            return currentCall != null || !queue.isEmpty() || !retryFutures.isEmpty();
        }
    }

    public void clearQueuedBacklog()
    {
        synchronized (queueLock)
        {
            queue.clear();
            if (currentCall != null)
            {
                currentCall.cancel();
                currentCall = null;
            }
            while (!retryFutures.isEmpty())
            {
                ScheduledFuture<?> future = retryFutures.pollFirst();
                if (future != null)
                {
                    future.cancel(false);
                }
            }
        }
    }

    public boolean submit(SyncPayload payload, UploadPriority priority, Consumer<UploadOutcome> callback)
    {
        if (!started || shuttingDown)
        {
            return false;
        }

        WebhookTarget target = resolveTarget();
        if (target == null)
        {
            if (callback != null)
            {
                callback.accept(new UploadOutcome(false, 0, null, "invalid webhook configuration", false));
            }
            return false;
        }

        QueuedUpload upload = new QueuedUpload(payload, priority, callback, target);
        synchronized (queueLock)
        {
            if (queue.size() >= MAX_QUEUE_SIZE)
            {
                if (priority == UploadPriority.LOW)
                {
                    if (callback != null)
                    {
                        callback.accept(new UploadOutcome(false, 0, null, "queue full", false));
                    }
                    return false;
                }

                while (queue.size() >= MAX_QUEUE_SIZE && removeLastLowPriority() != null)
                {
                    // keep removing low-priority work until a manual upload fits
                }

                if (queue.size() >= MAX_QUEUE_SIZE)
                {
                    QueuedUpload dropped = queue.pollFirst();
                    if (dropped != null && log.isDebugEnabled())
                    {
                        log.debug("Dropped oldest queued upload to make room for a manual sync request");
                    }
                }
            }

            queue.addLast(upload);
            if (currentCall == null)
            {
                drainQueue();
            }
        }

        return true;
    }

    private QueuedUpload removeLastLowPriority()
    {
        QueuedUpload lastLow = null;
        for (QueuedUpload queuedUpload : queue)
        {
            if (queuedUpload.priority == UploadPriority.LOW)
            {
                lastLow = queuedUpload;
            }
        }

        if (lastLow != null)
        {
            queue.removeLastOccurrence(lastLow);
        }
        return lastLow;
    }

    private void drainQueue()
    {
        if (shuttingDown || currentCall != null)
        {
            return;
        }

        QueuedUpload upload = queue.pollFirst();
        if (upload == null)
        {
            return;
        }

        Request request = buildRequest(upload);
        if (request == null)
        {
            complete(upload, new UploadOutcome(false, upload.attempt, null, "invalid request", false));
            return;
        }

        currentCall = httpClient.newBuilder()
            .connectTimeout(CONNECT_TIMEOUT)
            .callTimeout(CALL_TIMEOUT)
            .build()
            .newCall(request);

        currentCall.enqueue(new okhttp3.Callback()
        {
            @Override
            public void onFailure(Call call, java.io.IOException e)
            {
                currentCall = null;
                if (call.isCanceled() || shuttingDown)
                {
                    synchronized (queueLock)
                    {
                        drainQueue();
                    }
                    return;
                }
                if (upload.attempt < MAX_ATTEMPTS)
                {
                    scheduleRetry(upload, null, null);
                }
                else
                {
                    complete(upload, new UploadOutcome(false, upload.attempt, null, e.getClass().getSimpleName(), false));
                }
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response ignored = response)
                {
                    currentCall = null;
                    if (call.isCanceled() || shuttingDown)
                    {
                        synchronized (queueLock)
                        {
                            drainQueue();
                        }
                        return;
                    }
                    int code = response.code();
                    if (code >= 200 && code < 300)
                    {
                        complete(upload, new UploadOutcome(true, upload.attempt, code, "ok", false));
                        return;
                    }

                    if (isRetryable(code) && upload.attempt < MAX_ATTEMPTS)
                    {
                        scheduleRetry(upload, code, response.header("Retry-After"));
                        return;
                    }

                    complete(upload, new UploadOutcome(false, upload.attempt, code, "HTTP " + code, false));
                }
            }
        });
    }

    private void scheduleRetry(QueuedUpload upload, Integer code, String retryAfterHeader)
    {
        upload.attempt++;
        long delay = computeDelayMs(upload.attempt, retryAfterHeader);
        ScheduledFuture<?> future = executor.schedule(() ->
        {
            if (shuttingDown)
            {
                return;
            }

            synchronized (queueLock)
            {
                retryFutures.removeIf(ScheduledFuture::isDone);
            }

            synchronized (queueLock)
            {
                queue.addFirst(upload);
                if (currentCall == null)
                {
                    drainQueue();
                }
            }
        }, delay, TimeUnit.MILLISECONDS);

        synchronized (queueLock)
        {
            retryFutures.addLast(future);
        }

        if (upload.callback != null)
        {
            upload.callback.accept(new UploadOutcome(false, upload.attempt - 1, code, "retry scheduled", true));
        }
    }

    private long computeDelayMs(int attempt, String retryAfterHeader)
    {
        if (retryAfterHeader != null)
        {
            try
            {
                long seconds = Long.parseLong(retryAfterHeader.trim());
                if (seconds > 0)
                {
                    return TimeUnit.SECONDS.toMillis(seconds);
                }
            }
            catch (NumberFormatException ignored)
            {
            }
        }

        long base = BASE_RETRY_DELAY.toMillis() * (1L << Math.max(0, attempt - 1));
        return base + random.nextInt(250);
    }

    private boolean isRetryable(int code)
    {
        return code == 408 || code == 429 || code == 500 || code == 502 || code == 503 || code == 504;
    }

    private void complete(QueuedUpload upload, UploadOutcome outcome)
    {
        if (upload.callback != null)
        {
            upload.callback.accept(outcome);
        }

        synchronized (queueLock)
        {
            if (currentCall == null)
            {
                drainQueue();
            }
        }
    }

    private WebhookTarget resolveTarget()
    {
        String raw = config.clogPbWebhookUrl();
        if (raw == null || raw.trim().isEmpty())
        {
            return null;
        }

        HttpUrl parsed = HttpUrl.parse(raw.trim());
        if (parsed == null)
        {
            return null;
        }

        if (!"https".equalsIgnoreCase(parsed.scheme()))
        {
            return null;
        }

        WebhookMode mode = isDiscordWebhook(parsed) ? WebhookMode.DISCORD : WebhookMode.RECEIVER;
        if (mode == WebhookMode.RECEIVER)
        {
            String token = config.clogPbWebhookToken();
            if (token == null || token.trim().isEmpty())
            {
                return null;
            }
        }

        return new WebhookTarget(parsed, mode);
    }

    private Request buildRequest(QueuedUpload upload)
    {
        if (upload.target.mode == WebhookMode.DISCORD)
        {
            return buildDiscordRequest(upload);
        }

        String bodyJson = gson.toJson(upload.payload);
        byte[] bodyBytes = bodyJson.getBytes(StandardCharsets.UTF_8);
        String contentHash = sha256(bodyBytes);
        String timestamp = String.valueOf(System.currentTimeMillis());
        String nonce = java.util.UUID.randomUUID().toString();
        String signature = sign(upload.target.url, timestamp, nonce, contentHash);

        Request.Builder builder = new Request.Builder()
            .url(upload.target.url)
            .post(RequestBody.create(JSON, bodyJson))
            .header("User-Agent", TcCrewPlugin.USER_AGENT)
            .header("Authorization", "Bearer " + config.clogPbWebhookToken().trim())
            .header("X-Event-Id", upload.payload.getEventId())
            .header("X-Event-Type", upload.payload.getEventType())
            .header("X-Captured-At", upload.payload.getCapturedAt())
            .header("X-Timestamp", timestamp)
            .header("X-Nonce", nonce)
            .header("X-Content-SHA256", contentHash);

        if (signature != null)
        {
            builder.header("X-Signature", signature);
        }

        return builder.build();
    }

    private Request buildDiscordRequest(QueuedUpload upload)
    {
        String payloadJson = gson.toJson(upload.payload);
        JsonObject body = new JsonObject();
        body.addProperty("username", "Tangle Crew Plugin");
        JsonObject allowedMentions = new JsonObject();
        allowedMentions.add("parse", new JsonArray());
        body.add("allowed_mentions", allowedMentions);

        if (payloadJson.length() <= DISCORD_INLINE_JSON_LIMIT)
        {
            body.addProperty("content", "```json\n" + payloadJson + "\n```");
            return new Request.Builder()
                .url(upload.target.url)
                .post(RequestBody.create(JSON, gson.toJson(body)))
                .header("User-Agent", TcCrewPlugin.USER_AGENT)
                .build();
        }

        body.addProperty("content", "Raw JSON payload attached as " + DISCORD_JSON_FILENAME);
        MultipartBody multipart = new MultipartBody.Builder()
            .setType(MultipartBody.FORM)
            .addFormDataPart("payload_json", gson.toJson(body))
            .addFormDataPart("files[0]", DISCORD_JSON_FILENAME, RequestBody.create(JSON, payloadJson))
            .build();

        return new Request.Builder()
            .url(upload.target.url)
            .post(multipart)
            .header("User-Agent", TcCrewPlugin.USER_AGENT)
            .build();
    }

    private boolean isDiscordWebhook(HttpUrl url)
    {
        String host = url.host().toLowerCase(java.util.Locale.ROOT);
        String path = url.encodedPath().toLowerCase(java.util.Locale.ROOT);
        return (host.endsWith("discord.com") || host.endsWith("discordapp.com"))
            && path.contains("/api/webhooks/");
    }

    private String sign(HttpUrl url, String timestamp, String nonce, String contentHash)
    {
        String secret = config.clogPbSigningSecret();
        if (secret == null || secret.trim().isEmpty())
        {
            return null;
        }

        try
        {
            String canonical = String.join("\n", "POST", url.encodedPath(), timestamp, nonce, contentHash);
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.trim().getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            return toHex(mac.doFinal(canonical.getBytes(StandardCharsets.UTF_8)));
        }
        catch (Exception ex)
        {
            log.debug("Unable to sign sync request", ex);
            return null;
        }
    }

    private String sha256(byte[] bytes)
    {
        try
        {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return toHex(digest.digest(bytes));
        }
        catch (Exception ex)
        {
            throw new IllegalStateException(ex);
        }
    }

    private String toHex(byte[] bytes)
    {
        char[] hex = new char[bytes.length * 2];
        final char[] digits = "0123456789abcdef".toCharArray();
        for (int i = 0; i < bytes.length; i++)
        {
            int b = bytes[i] & 0xff;
            hex[i * 2] = digits[b >>> 4];
            hex[i * 2 + 1] = digits[b & 0x0f];
        }
        return new String(hex);
    }

    private static final class QueuedUpload
    {
        private final SyncPayload payload;
        private final UploadPriority priority;
        private final Consumer<UploadOutcome> callback;
        private final WebhookTarget target;
        private int attempt = 1;

        private QueuedUpload(SyncPayload payload, UploadPriority priority, Consumer<UploadOutcome> callback, WebhookTarget target)
        {
            this.payload = Objects.requireNonNull(payload);
            this.priority = Objects.requireNonNull(priority);
            this.callback = callback;
            this.target = Objects.requireNonNull(target);
        }
    }

    private enum WebhookMode
    {
        RECEIVER,
        DISCORD
    }

    private static final class WebhookTarget
    {
        private final HttpUrl url;
        private final WebhookMode mode;

        private WebhookTarget(HttpUrl url, WebhookMode mode)
        {
            this.url = url;
            this.mode = mode;
        }
    }
}

package tccrewplugin.sync.webhook;

import lombok.Value;

@Value
public class UploadOutcome
{
    boolean success;
    int attempts;
    Integer statusCode;
    String message;
    boolean retryScheduled;
}

package tccrewplugin.sync.webhook;

public enum UploadPriority
{
    HIGH,
    LOW
}

package tccrewplugin.util;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.annotations.SerializedName;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Setter;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.util.*;
import java.util.stream.Collectors;

@Slf4j
public abstract class AbstractRarityService {

    protected final Gson gson;
    protected final ItemManager itemManager;
    protected final Map<String, Collection<RareDrop>> dropsBySourceName;

    AbstractRarityService(String resourceName, int expectedSize, Gson gson, ItemManager itemManager) {
        this.gson = gson;
        this.itemManager = itemManager;
        this.dropsBySourceName = new HashMap<>(expectedSize);

        Map<String, List<RawDrop>> raw;
        try (InputStream is = getClass().getResourceAsStream(resourceName);
             Reader reader = new BufferedReader(new InputStreamReader(Objects.requireNonNull(is)))) {
            JsonObject root = gson.fromJson(reader, JsonObject.class);
            raw = new HashMap<>();
            if (root != null) {
                for (Map.Entry<String, JsonElement> entry : root.entrySet()) {
                    JsonArray array = entry.getValue().getAsJsonArray();
                    RawDrop[] drops = gson.fromJson(array, RawDrop[].class);
                    raw.put(entry.getKey(), drops == null ? Collections.emptyList() : Arrays.asList(drops));
                }
            }
        } catch (Exception e) {
            log.error("Failed to read monster drop rates", e);
            return;
        }

        raw.forEach((sourceName, rawDrops) -> {
            ArrayList<RareDrop> drops = rawDrops.stream()
                .map(RawDrop::transform)
                .flatMap(Collection::stream)
                .collect(Collectors.toCollection(ArrayList::new));
            drops.trimToSize();
            dropsBySourceName.put(sourceName, drops);
        });
    }

    public OptionalDouble getRarity(String sourceName, int itemId, int quantity) {
        ItemComposition composition = itemId >= 0 ? itemManager.getItemComposition(itemId) : null;
        int canonical = composition != null && composition.getNote() != -1 ? composition.getLinkedNoteId() : itemId;
        String itemName = composition != null ? composition.getMembersName() : "";
        Collection<Integer> variants = new HashSet<>(
            ItemVariationMapping.getVariations(ItemVariationMapping.map(canonical))
        );
        return dropsBySourceName.getOrDefault(sourceName, Collections.emptyList())
            .stream()
            .filter(drop -> drop.getMinQuantity() <= quantity && quantity <= drop.getMaxQuantity())
            .filter(drop -> {
                int id = drop.getItemId();
                if (id == itemId) return true;
                return variants.contains(id) && itemName.equals(itemManager.getItemComposition(id).getMembersName());
            })
            .mapToDouble(RareDrop::getProbability)
            .reduce(Double::sum);
    }

    @Value
    protected static class RareDrop {
        int itemId;
        int minQuantity;
        int maxQuantity;
        double probability;
    }

    @Data
    @Setter(AccessLevel.PRIVATE)
    private static class RawDrop {
        private @SerializedName("i") int itemId;
        private @SerializedName("r") Integer rolls;
        private @SerializedName("d") double denominator;
        private @SerializedName("q") Integer quantity;
        private @SerializedName("m") Integer quantMin;
        private @SerializedName("n") Integer quantMax;

        Collection<RareDrop> transform() {
            int rounds = rolls != null ? rolls : 1;
            int min = quantMin != null ? quantMin : quantity;
            int max = quantMax != null ? quantMax : quantity;
            double prob = 1 / denominator;

            if (rounds == 1) {
                return List.of(new RareDrop(itemId, min, max, prob));
            }
            List<RareDrop> drops = new ArrayList<>(rounds);
            for (int successCount = 1; successCount <= rounds; successCount++) {
                double density = MathUtils.binomialProbability(prob, rounds, successCount);
                drops.add(new RareDrop(itemId, min * successCount, max * successCount, density));
            }
            return drops;
        }
    }
}

package tccrewplugin.util;

import tccrewplugin.domain.AccountType;
import tccrewplugin.domain.FilterMode;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Player;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarbitID;

import javax.inject.Singleton;

@Slf4j
@Singleton
public class AccountTypeTracker extends BooleanStateTracker {

    @Override
    protected void populateState() {
        Player player = client.getLocalPlayer();
        var accountType = AccountType.get(client.getVarbitValue(VarbitID.IRONMAN));
        if (player == null || player.getName() == null || accountType == null) {
            this.state = null;
            return;
        } else if (config.nameFilterMode() != FilterMode.ALLOW && config.deniedAccountTypes().contains(accountType)) {
            this.state = false;
        } else {
            this.state = settingsManager.isNamePermitted(player.getName());
        }
        log.debug("Initialized account tracker for {} {}: {}", accountType, player.getName(), this.state);
    }

    public void onVarbit(VarbitChanged event) {
        if (event.getVarbitId() == VarbitID.IRONMAN) {
            this.refresh();
        }
    }

    public void onAccountChange() {
        this.refresh();
    }

    public void onConfig(String configKey) {
        if ("nameFilterMode".equals(configKey) || "deniedAccountTypes".equals(configKey) || "ignoredNames".equals(configKey)) {
            this.refresh();
        }
    }

}

package tccrewplugin.util;

import tccrewplugin.TangleCrewConfig;
import tccrewplugin.SettingsManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;

import javax.inject.Inject;

@Slf4j
public abstract class BooleanStateTracker {

    @Inject
    protected TangleCrewConfig config;

    @Inject
    protected SettingsManager settingsManager;

    @Inject
    protected Client client;

    @Inject
    protected ClientThread clientThread;

    protected volatile Boolean state;

    public void init() {
        clientThread.invoke(() -> {
            if (client.getGameState() == GameState.LOGGED_IN && !settingsManager.justLoggedIn()) {
                this.populateState();
            }
        });
    }

    public void clear() {
        this.state = null;
    }

    public boolean hasValidState() {
        Boolean valid = this.state;
        return valid != null && valid;
    }

    public void onTick() {
        if (this.state == null && !settingsManager.justLoggedIn()) {
            populateState();
        }
    }

    protected void refresh() {
        this.clear();
        this.init();
    }

    protected abstract void populateState();

}

package tccrewplugin.util;

import com.google.gson.TypeAdapter;
import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonWriter;

import java.awt.Color;
import java.io.IOException;

/**
 * Serializes and deserializes {@link Color} instances
 * from their decimal representation.
 * <p>
 * Discord requires this decimal format, rather than a hex string
 * that the default RuneLite GSON instance would produce.
 */
public class ColorAdapter extends TypeAdapter<Color> {
    @Override
    public void write(JsonWriter out, Color color) throws IOException {
        out.value(color != null ? color.getRGB() ^ 0xFF000000 : null);
    }

    @Override
    public Color read(JsonReader in) throws IOException {
        if (in.hasNext()) {
            return new Color(in.nextInt());
        }
        return null;
    }
}

package tccrewplugin.util;

import tccrewplugin.TangleCrewConfig;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Authenticator;
import okhttp3.Credentials;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.Route;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

@Slf4j
@RequiredArgsConstructor
public final class ConfigProxyAuth implements Authenticator {

    private final TangleCrewConfig config;

    @Override
    @Nullable
    public Request authenticate(@Nullable Route route, @NotNull Response response) {
        var server = config.proxyServer();
        if (server == null || server.isBlank()) {
            return null;
        }

        var auth = config.proxyAuth();
        if (auth == null || auth.isBlank()) {
            return null;
        }

        int delim = auth.indexOf(':');
        if (delim < 0) {
            log.warn("Proxy auth must be specified in user:pass format");
            return null;
        }

        var username = auth.substring(0, delim);
        var password = auth.substring(delim + 1);

        return response.request()
            .newBuilder()
            .header("Proxy-Authorization", Credentials.basic(username, password))
            .build();
    }

}

package tccrewplugin.util;

import tccrewplugin.TangleCrewConfig;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.Proxy;
import java.net.ProxySelector;
import java.net.SocketAddress;
import java.net.URI;
import java.util.List;

@Slf4j
@RequiredArgsConstructor
public final class ConfigProxyServer extends ProxySelector {
    private static final List<Proxy> NONE = List.of(Proxy.NO_PROXY);

    private final TangleCrewConfig config;

    @Override
    public List<Proxy> select(URI uri) {
        var server = config.proxyServer();
        if (server == null || server.isBlank()) {
            return NONE;
        }

        int delim = server.lastIndexOf(':');
        if (delim < 0) {
            log.warn("Proxy server must be specified in host:port format");
            return NONE;
        }

        var host = server.substring(0, delim);
        var portStr = server.substring(delim + 1);

        int port;
        try {
            port = Integer.parseInt(portStr);
        } catch (NumberFormatException e) {
            log.warn("Port for proxy server must be an integer");
            return NONE;
        }

        try {
            var addr = new InetSocketAddress(host, port);
            var proxy = new Proxy(Proxy.Type.HTTP, addr);
            return List.of(proxy);
        } catch (Exception e) {
            log.warn("Proxy server could not be configured", e);
            return NONE;
        }
    }

    @Override
    public void connectFailed(URI uri, SocketAddress socketAddress, IOException e) {
        // no op
    }

}

package tccrewplugin.util;

import com.google.gson.Gson;
import lombok.experimental.UtilityClass;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.util.ColorUtil;
import org.apache.commons.lang3.StringUtils;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import java.util.Collection;
import java.util.regex.Pattern;
import java.util.stream.Stream;

@UtilityClass
public class ConfigUtil {

    private final Pattern DELIM = Pattern.compile("[,;\\n]");

    public Stream<String> readDelimited(String value) {
        if (value == null) return Stream.empty();
        return DELIM.splitAsStream(value)
            .map(String::trim)
            .filter(StringUtils::isNotEmpty);
    }

    public boolean isPluginDisabled(ConfigManager configManager, String simpleLowerClassName) {
        return "false".equals(configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, simpleLowerClassName));
    }

    @Nullable
    public String toRawConfigValue(@NotNull Gson gson, @NotNull Object in) {
        if (in instanceof String) {
            return (String) in;
        }
        if (in instanceof Number || in instanceof Boolean || in instanceof Character) {
            return String.valueOf(in);
        }
        if (in instanceof Enum<?>) {
            return ((Enum<?>) in).name();
        }
        if (in instanceof Color) {
            return ColorUtil.colorToHexCode((Color) in);
        }
        if (in instanceof Instant || in instanceof Duration) {
            return in.toString();
        }
        if (in instanceof Collection<?>) {
            return gson.toJson(in);
        }
        return gson.toJson(in);
    }

    public boolean isSettingsOpen(@NotNull Client client) {
        Widget widget = client.getWidget(InterfaceID.Settings.UNIVERSE);
        return widget != null && !widget.isHidden();
    }

    public boolean isKillCountFilterInvalid(int varbitValue) {
        // spam filter must be disabled for kill count chat message
        return varbitValue > 0;
    }

    public boolean isCollectionLogInvalid(int varbitValue) {
        // collection log notifier requires chat or pop-up notification
        return varbitValue == 0;
    }

    public boolean isRepeatPopupInvalid(int varbitValue) {
        // we discourage repeat notifications for combat task notifier if unintentional
        return varbitValue > 0;
    }

    public boolean isPetLootInvalid(int varbitValue) {
        // LOOT_DROP_NOTIFICATIONS and UNTRADEABLE_LOOT_DROPS must both be set to 1 for reliable pet name parsing
        return varbitValue < 1;
    }
}

